return function(Plasma)
	local create = Plasma.create
	return Plasma.widget(function(children, debugger)
		local clicked, setClicked = Plasma.useState(false)
		local refs = Plasma.useInstance(function(ref)
			local style = Plasma.useStyle()

			local frame = create("Frame", {
				[ref] = "panel",
				Name = "Panel",
				BackgroundColor3 = style.bg2,
				Position = UDim2.new(0, 0, 0, 0),
				Size = UDim2.new(0, 250, 1, 0),

				create("Frame", {
					-- Account for GUI inset
					-- GuiService:GetGuiInset returns wrong info on the server :(
					Size = UDim2.new(1, 0, 0, style.guiInset),
					BackgroundColor3 = Color3.new(0, 0, 0),
					BackgroundTransparency = 0.5,
					ZIndex = 999,

					create("TextLabel", {
						Position = UDim2.new(1, -10, 0.5, 0),
						AnchorPoint = Vector2.new(1, 0.5),
						BackgroundTransparency = 1,
						Size = UDim2.new(0, 110, 0, 25),
						Text = "WuKong",
						TextScaled = true,
						ZIndex = 999,
						TextColor3 = Color3.new(1, 0, 0),
						Font = Enum.Font.GothamBold
					}),

					create("TextButton", {
						[ref] = "userBtn",
						Size = UDim2.new(0, 120, 0, 25),
						BackgroundColor3 = Color3.fromRGB(88, 224, 248),
						BackgroundTransparency = .5,
						AnchorPoint = Vector2.new(0, 0),
						Position = UDim2.fromScale(0, 1),
						Visible = true,
						ZIndex = 999,
						Text = "",

						create("TextLabel", {
							[ref] = "userLabel",
							AnchorPoint = Vector2.new(.5, .5),
							Position = UDim2.fromScale(.5, .5),
							Size = UDim2.fromScale(1, 1),
							Text = "",
							BackgroundTransparency = 1,
							TextColor3 = Color3.fromRGB(255, 255, 255),
							ZIndex = 999,
							Font = Enum.Font.GothamBold,
							TextScaled = true
						}),
						Activated = function()
							setClicked(true)
						end,
					}),

					create("Frame", {
						Size = UDim2.new(0, 60, 0, 25),
						BackgroundColor3 = Color3.fromRGB(229, 195, 0),
						BackgroundTransparency = 0.5,
						AnchorPoint = Vector2.new(1, 0),
						Position = UDim2.fromScale(1, 1),
						Visible = debugger._isClientDev,
						ZIndex = 999,

						create("TextLabel", {
							AnchorPoint = Vector2.new(.5, .5),
							Position = UDim2.fromScale(.5, .5),
							Size = UDim2.fromScale(.8, 1),
							Text = "ClientDev",
							BackgroundTransparency = 1,
							TextColor3 = Color3.fromRGB(255, 255, 255),
							ZIndex = 999,
							Font = Enum.Font.GothamBold,
							TextScaled = true
						})
					})
				}),

				create("UIStroke", {}),

				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					HorizontalAlignment = Enum.HorizontalAlignment.Center,
				}),

				create("ScrollingFrame", {
					BackgroundTransparency = 1,
					Name = "Container",
					VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar,
					HorizontalScrollBarInset = Enum.ScrollBarInset.ScrollBar,
					BorderSizePixel = 0,
					ScrollBarThickness = 6,
					Size = UDim2.new(1, 0, 0, 0),

					create("UIPadding", {
						PaddingTop = UDim.new(0, 20),
						PaddingLeft = UDim.new(0, 10),
						PaddingRight = UDim.new(0, 10),
					}),

					create("UIListLayout", {
						SortOrder = Enum.SortOrder.LayoutOrder,
					}),
				}),
			})

			Plasma.automaticSize(frame.Container, {
				axis = Enum.AutomaticSize.Y,
				maxSize = UDim2.new(1, 0, 1, -46),
			})
			return frame, frame.Container
		end)
		refs.userLabel.Text = debugger.CurrentUserId
		-- Plasma.useEffect(function()
		-- 	refs.panel.Size = debugger._mini and UDim2.fromOffset(0, 0) or UDim2.new(0, 250, 1, 0)
		-- end, debugger._mini)
		Plasma.scope(children)

		local handle = {
			clicked = function()
				if clicked then
					setClicked(false)
					return true
				end
				return false
			end,
		}
		return handle
	end)
end
